// ── CASOAEROPUERTO STG5 — Legal dashboard → animated scene ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — all provided by the runtime

// Sky gradient override
svg += `<defs><linearGradient id="lg-aeropuerto" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${isN ? '#0E1A3A' : sc.sky1}"/><stop offset="100%" stop-color="${isN ? '#223366' : sc.sky2}"/></linearGradient></defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-aeropuerto)"/>`;

// Ground / environment zone
svg += `<rect x="0" y="${bY}" width="${w}" height="${h - bY}" fill="${sc.ground}"/>`;
// Breathing environmental pressure
svg += `<rect x="0" y="${bY}" width="${w * w1}" height="${h - bY}" fill="#4E8A66" opacity="0.4"/>`;

// Floating legal header banner
const headerY = h * 0.06 + Math.sin(mt) * 5;
svg += `<rect x="${w * 0.1}" y="${headerY}" width="${w * 0.8}" height="52" rx="8" fill="${sc.bld}" opacity="0.95"/>`;
svg += `<text x="${w * 0.5}" y="${headerY + 22}" text-anchor="middle" fill="#EDE8DF" font-size="13" font-weight="bold" font-family="serif">🛫 Caso Aeropuerto 5</text>`;
svg += `<text x="${w * 0.5}" y="${headerY + 40}" text-anchor="middle" fill="${sc.acc}" font-size="10" font-family="monospace">CBA Framework · Art. 208 · 29 Segments · Severity: MEDIUM</text>`;

// Warning marker (pulsing amber — medium severity)
const warnPulse = Math.sin(mt * 2.5) * 0.5 + 0.5;
svg += `<circle cx="${w * 0.12}" cy="${bY - 20 + Math.sin(mt * 2) * 3}" r="${6 + warnPulse * 3}" fill="${sc.acc}" opacity="${0.7 + warnPulse * 0.3}"/>`;

// Terminal buildings (infrastructure blocks — 4 segments)
for (let i = 0; i < 4; i++) {
  const bw2 = 40 + w2 * 8;
  const bx = w * 0.2 + i * (bw2 + 18);
  const bh2 = 55 + w2 * 20;
  svg += `<rect x="${bx}" y="${bY - bh2}" width="${bw2}" height="${bh2}" fill="${sc.bld}" rx="4" stroke="#3A3228" stroke-width="${ol * 0.6}"/>`;
  // Control tower on first block
  if (i === 0) {
    svg += `<rect x="${bx + bw2 / 2 - 5}" y="${bY - bh2 - 20}" width="10" height="20" fill="${sc.bld}" stroke="#3A3228" stroke-width="${ol * 0.5}"/>`;
    svg += `<circle cx="${bx + bw2 / 2}" cy="${bY - bh2 - 22}" r="7" fill="${sc.acc}" stroke="#3A3228" stroke-width="${ol * 0.4}"/>`;
  }
  // Animated windows (legal activity markers)
  for (let j = 0; j < 3; j++) {
    const wpulse = Math.sin(mt * 2.1 + i * 1.3 + j * 0.9) * 0.5 + 0.5;
    const wfill = isN ? `rgba(255,213,80,${0.4 + wpulse * 0.5})` : `rgba(180,160,120,${0.15 + wpulse * 0.1})`;
    svg += `<rect x="${bx + 8}" y="${bY - bh2 + 10 + j * 14}" width="8" height="8" rx="1" fill="${wfill}"/>`;
    if (isN) svg += `<ellipse cx="${bx + 12}" cy="${bY - bh2 + 14 + j * 14}" rx="12" ry="8" fill="rgba(255,213,80,0.05)"/>`;
  }
}

// Runway
const runwayY = bY - 8;
svg += `<rect x="${w * 0.05}" y="${runwayY}" width="${w * 0.9}" height="8" fill="#2F2F2F" rx="2"/>`;
for (let i = 0; i < 12; i++) {
  const dashX = w * 0.08 + i * (w * 0.07);
  const dashOpacity = 0.5 + w1 * 0.5;
  svg += `<rect x="${dashX}" y="${runwayY + 3}" width="12" height="2" fill="white" opacity="${dashOpacity}"/>`;
}

// Animated airplane (flying across runway)
const planeX = w * 0.05 + w1 * (w * 0.88);
const planeY = runwayY - 22 - Math.sin(mt * 3) * 6;
svg += `<polygon points="${planeX + 16},${planeY} ${planeX - 4},${planeY + 6} ${planeX - 4},${planeY - 6}" fill="#EDE8DF" stroke="#3A3228" stroke-width="${ol * 0.3}"/>`;
svg += `<polygon points="${planeX + 2},${planeY - 6} ${planeX - 10},${planeY - 14} ${planeX - 14},${planeY - 6}" fill="${sc.acc}" opacity="0.85"/>`;
svg += `<polygon points="${planeX - 2},${planeY + 6} ${planeX - 10},${planeY + 14} ${planeX - 14},${planeY + 6}" fill="${sc.acc}" opacity="0.85"/>`;

// Night mode atmosphere
if (isN) {
  svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="#000" opacity="0.25"/>`;
  // Runway lights
  for (let i = 0; i < 10; i++) {
    const lx = w * 0.08 + i * (w * 0.085);
    const lPulse = Math.sin(mt * 3 + i * 0.6) * 0.5 + 0.5;
    svg += `<circle cx="${lx}" cy="${runwayY - 2}" r="2" fill="#FFD54F" opacity="${0.4 + lPulse * 0.6}"/>`;
  }
}
